// Safely attempt to get the staff ID by checking nodes independently
let staffId = null;
let isManuallyCorrected = false; // New flag to track if this was manually corrected

// Attempt 1: 'clean data' node
try {
  const cleanDataNode = $('clean data').first();
  if (cleanDataNode && cleanDataNode.json.staff_id) {
    staffId = cleanDataNode.json.staff_id;
  }
} catch (error) {
  // Node didn't run or data is missing, move on
}

// Attempt 2: 'SAST image from phone' node
if (!staffId) {
  try {
    const phoneNode = $('SAST image from phone').first();
    if (phoneNode && phoneNode.json.body && phoneNode.json.body.user_id) {
      staffId = phoneNode.json.body.user_id;
    }
  } catch (error) {
    // Node didn't run or data is missing
  }
}

// Attempt 3: 'sast-manual-correction' node
try {
  const manualNode = $('sast-manual-correction').first();
  if (manualNode) {
    // If this node executed without throwing an error, we know it's a manual correction!
    isManuallyCorrected = true; 

    // Check for the user_id in the manual correction payload if we don't have a staffId yet
    if (!staffId && manualNode.json.body && manualNode.json.body.user_id) {
      staffId = manualNode.json.body.user_id;
    }
  }
} catch (error) {
  // Node didn't run, meaning this is an automated run
}

// Map the raw data and include the new database flags
const rawData = $input.all().map(item => {
  const r = item.json;
  return {
    json: {
      instructor_ID: r['instructor_ID'] || null,
      subject_id: r['true_subject_id'] || null,
      term_id: r['current_term_id'] || null,
      student_id: r['Student ID'] || null,
      instructor: r['Instructor/Professor'] || null,

      m1: Number(r['M1']) || null,
      m2: Number(r['M2']) || null,
      m3: Number(r['M3']) || null,
      m4: Number(r['M4']) || null,
      m5: Number(r['M5']) || null,
      m6: Number(r['M6']) || null,
      m7: Number(r['M7']) || null,
      m8: Number(r['M8']) || null,
      m9: Number(r['M9']) || null,
      m10: Number(r['M10']) || null,

      p1: Number(r['P1']) || null,
      p2: Number(r['P2']) || null,
      p3: Number(r['P3']) || null,
      p4: Number(r['P4']) || null,
      p5: Number(r['P5']) || null,
      p6: Number(r['P6']) || null,
      p7: Number(r['P7']) || null,
      p8: Number(r['P8']) || null,
      p9: Number(r['P9']) || null,
      p10: Number(r['P10']) || null,

      Remarks_and_Suggestions: String(r['Remarks & Suggestions'] ?? '').trim() || null,

      submitted_date: r['Date'] ? new Date(r['Date']).toISOString().split('T')[0] : null,

      sao_staff_id: staffId,

      // ADDED: Map to the columns shown in your Supabase screenshot
      manually_corrected: isManuallyCorrected,
      validation_status: isManuallyCorrected ? 'corrected' : 'auto'
    }
  };
});

const uniqueData = [];
const seen = new Set();

// Loop backwards to keep the newest submission and discard older duplicates
for (let i = rawData.length - 1; i >= 0; i--) {
  const item = rawData[i];
  const j = item.json;

  // The magic fingerprint checking Student + Instructor + Subject + Term
  const uniqueKey = `${j.student_id}_${j.instructor_ID}_${j.subject_id}_${j.term_id}`;

  if (!seen.has(uniqueKey)) {
    seen.add(uniqueKey);
    uniqueData.push(item);
  }
}

return uniqueData.reverse();

const grouped = {};
let current_term = null; 

for (const item of items) {
  const instructor = item.json.instructor_ID;
  const remark = item.json["Remarks & Suggestions"];

  // Safely capture the term_id from the incoming data
  if (item.json.current_term_id) {
     current_term = item.json.current_term_id;
  }

  if (!remark) continue; 

  if (!grouped[instructor]) {
    grouped[instructor] = [];
  }
  grouped[instructor].push(remark);
}

return Object.entries(grouped).map(([instructor_ID, remarks]) => {
  return {
    json: {
      instructor_ID,
      term_id: current_term,  // <--- Passing it down the chain!
      remarks
    }
  };
});

const newItems = [];

for (const item of items) {
  const aiResponse = item.json.text;

  // Strip markdown code fences
  let clean = aiResponse
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  // ✅ Extract only the JSON object — ignores truncated/extra text
  const jsonMatch = clean.match(/\{[\s\S]*\}/);
  if (!jsonMatch) {
    console.log('No JSON found, skipping. Raw:', clean.substring(0, 100));
    continue; // skip instead of crash
  }

  let result;
  try {
    result = JSON.parse(jsonMatch[0]);
  } catch (e) {
    console.log('JSON parse failed:', e.message);
    console.log('Raw text:', clean.substring(0, 200));
    continue; // skip instead of crash
  }

  const instructor_id = $('Loop Over Items6').item.json.instructor_ID;
  const term_id = $('Loop Over Items6').item.json.term_id;

  for (const k of result.keywords || []) {
    newItems.push({
      json: {
        instructor_id: instructor_id,
        term_id: term_id,
        word: k.word,
        count: k.count
      }
    });
  }
}

return newItems;

// 1. Grab everything safely from the Loop node
const loopData = $('Loop Over Items7').item.json;

// 2. Extract the remarks array (with a safety net)
const remarksArray = loopData.remarks || [];

// 3. Join them into a nice bulleted list string
const formatted_remarks = "- " + remarksArray.join('\n- ');

// 4. Output a clean item with BOTH IDs for the AI node
return [
  {
    json: {
      instructor_ID: loopData.instructor_ID,
      term_id: loopData.term_id,            // <--- Passing the term_id forward!
      formatted_remarks: formatted_remarks
    }
  }
];

// 1. Get the raw text from Gemini
const aiResponse = $input.item.json.text;

// 2. Bulletproof cleanup (Fixed the accidental line break here!)
const clean = aiResponse.replace(/```json/gi, "").replace(/```/g, "").trim();
const parsed = JSON.parse(clean);

// 3. Retrieve BOTH IDs directly from the Loop node
const loopData = $('Loop Over Items7').item.json;

// 4. Safety Net: Convert arrays to strings just in case Gemini makes a list
const formatText = (data) => Array.isArray(data) ? "- " + data.join('\n- ') : data;

return [
  {
    json: {
      instructor_id: loopData.instructor_ID,
      term_id: loopData.term_id,            
      ai_suggestion: formatText(parsed.suggestion),
      student_interpretation: formatText(parsed.interpretation),
      positive_themes: formatText(parsed.positives),
      improvement_insights: formatText(parsed.improvements)
    }
  }
];

// 1. Get the raw text from the Gemini node
const aiText = $input.item.json.text;

// 2. Clean and parse the AI JSON
const jsonStart = aiText.indexOf('{');
const jsonEnd = aiText.lastIndexOf('}') + 1;
const clean = aiText.substring(jsonStart, jsonEnd);
const parsed = JSON.parse(clean);

// 3. THE ULTIMATE SAFETY NET
let rawTone = String(parsed.tone).toLowerCase().trim();
let finalTone = "Neutral"; // Assume Neutral by default

if (rawTone.includes("positive")) {
    finalTone = "Positive";
} else if (rawTone.includes("critical")) {
    finalTone = "Critical";
}

// 4. Grab your original form data safely from the Loop node
const originalData = $('Loop Over Items8').item.json;

// 5. Combine them and output one clean object for Supabase
return {
  json: {
    instructor_ID: originalData.instructor_ID,
    subject_id: originalData.true_subject_id,   // Fixed: Now sending the UUID, not the text!
    term_id: originalData.current_term_id,      // Added: The Term ID
    remark: originalData['Remarks & Suggestions'],
    tone: finalTone 
  }
};

