// Grab ALL 205 items from the If node
const allItems = $('If').all();
const uniquePairs = {};

// Loop through all of them and find every unique Instructor + Term combo
for (const item of allItems) {
  const instId = item.json.instructor_ID;
  const termId = item.json.current_term_id;

  if (instId && termId) {
    uniquePairs[`${instId}_${termId}`] = {
      instructor_id: instId,
      term_id: termId
    };
  }
}

// Return the full list of unique instructors so Postgres updates ALL of them
return Object.values(uniquePairs).map(pair => ({ json: pair }));

const items = $input.all();

return items.map(item => {
  // n8n Webhook data is usually inside item.json.body
  const payload = item.json.body || item.json;

  const staffId = payload.user_id;
  const googleLink = payload.link;
  let sheetId = '';

  if (googleLink && typeof googleLink === 'string') {
    const match = googleLink.match(/\/d\/(.*?)(\/|$)/);
    if (match && match[1]) {
      sheetId = match[1];
    }
  }

  return {
    json: {
      staff_id: staffId,
      google_link: googleLink,
      sheetId: sheetId,  // Changed this so the Google Node recognizes it automatically!
      import_type: payload.type,
      sync_time: payload.timestamp
    }
  };
});

// Mode: Run Once for Each Item
const base64Data = $input.item.json.body.image;
const taskId     = $input.item.json.body.task_id;
const userId     = $input.item.json.body.user_id;
const timestamp  = $input.item.json.body.timestamp;
const termId     = $input.item.json.body.term_id;      // ← ADD
const filename   = $input.item.json.body.filename;     // ← ADD
const paperSize  = $input.item.json.body.paper_size;   // ← ADD

if (!base64Data) {
  throw new Error('No image data in request body');
}

const cleanBase64 = base64Data.includes(',')
  ? base64Data.split(',')[1]
  : base64Data;

const buffer     = Buffer.from(cleanBase64, 'base64');
const binaryData = await this.helpers.prepareBinaryData(
  buffer,
  `${taskId}.jpg`,
  'image/jpeg'
);

return {
  binary: { data: binaryData },
  json: {
    user_id    : userId,
    term_id    : termId,      // ← ADD
    task_id    : taskId,
    filename   : filename,    // ← ADD
    paper_size : paperSize,   // ← ADD
    timestamp  : timestamp,
  }
};

